    plan = plan.replace('## Журнал изменений\n', '## Журнал изменений\n\n' + entry, 1)
    save(plan_path, plan)
    print(json.dumps(dict(registered=list(IDS), protocol=str(RUN / 'protocol.json'), moscow=now.isoformat()), ensure_ascii=False))


